export function validateTrainingReadinessRegistry(): readonly string[] {
  const errors: string[] = [];
  for (const [key, expected] of Object.entries(expectedRegistryCounts)) {
    const actual = registryCounts[key as keyof typeof registryCounts];
    if (actual !== expected) errors.push(`${key}: expected ${expected}, received ${actual}`);
  }
  for (const journey of roleJourneyRegistry) {
    const row = workbookPathwaySummary.find((item) => item.pathway === journey.role) as { recommendedTotal?: number; policyAssignmentRows?: number } | undefined;
    const countsForRole = journey.counts as { courses: number; policyActivities: number };
    if (!row) errors.push(`${journey.role}: missing workbook pathway summary`);
    else {
      if (row.recommendedTotal !== countsForRole.courses) errors.push(`${journey.role}: course count differs from workbook`);
      if (row.policyAssignmentRows !== countsForRole.policyActivities) errors.push(`${journey.role}: policy activity count differs from workbook`);
    }
  }
  if (coursePolicyMappings.some((item) => !item.completionRequirements.readFullPolicy || !item.completionRequirements.attestation || !item.completionRequirements.scoredBundledQuiz)) errors.push('Every mapped policy must require read + attestation + bundled scored quiz.');
  if (rolePolicyActivities.some((item) => (item.launchContract as { ordinaryDetailDrawerAllowed?: boolean }).ordinaryDetailDrawerAllowed !== false)) errors.push('Every role policy activity must prohibit ordinary detail-drawer launch.');
  return Object.freeze(errors);
}
